import{_ as t,o,c,a3 as d}from"./chunks/framework.BTQ4eCVb.js";const h=JSON.parse('{"title":"Tenant API v1 — Products","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Tenant API v1 — Products | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/api/tenant-v1-products"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Tenant API v1 — Products | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/api/tenant-v1-products"}]]},"headers":[],"relativePath":"api/tenant-v1-products.md","filePath":"api/tenant-v1-products.md","lastUpdated":1788177646000}'),r={name:"api/tenant-v1-products.md"};function a(s,e,u,n,i,p){return o(),c("div",null,[...e[0]||(e[0]=[d('<h1 id="tenant-api-v1-—-products" tabindex="-1">Tenant API v1 — Products <a class="header-anchor" href="#tenant-api-v1-—-products" aria-label="Permalink to &quot;Tenant API v1 — Products&quot;">​</a></h1><p>Base path: <code>/api/tenant/v1</code>. All endpoints require authenticated, verified tenant access, <code>module:products</code>, and the stated <code>products.*</code> permission.</p><h2 id="products" tabindex="-1">Products <a class="header-anchor" href="#products" aria-label="Permalink to &quot;Products&quot;">​</a></h2><h3 id="get-products-stats" tabindex="-1">GET <code>/products/stats</code> <a class="header-anchor" href="#get-products-stats" aria-label="Permalink to &quot;GET `/products/stats`&quot;">​</a></h3><p>Returns product KPI totals.</p><h3 id="get-products-next-sku" tabindex="-1">GET <code>/products/next-sku</code> <a class="header-anchor" href="#get-products-next-sku" aria-label="Permalink to &quot;GET `/products/next-sku`&quot;">​</a></h3><p>Requires <code>products.create</code>. Returns the next suggested SKU (<code>{ sku }</code>), using tenant setting <code>products_sku_prefix</code> (default <code>SKU-</code>) plus a zero-padded sequence. Soft-deleted products count toward the sequence. The value is a preview — concurrent creates may advance it; omit <code>sku</code> on create to let the server assign safely.</p><h3 id="get-products" tabindex="-1">GET <code>/products</code> <a class="header-anchor" href="#get-products" aria-label="Permalink to &quot;GET `/products`&quot;">​</a></h3><p>Query: <code>search</code>, <code>category_id</code>, <code>status</code> (<code>active|inactive</code>), <code>trashed</code> (<code>true|only</code>), <code>sort</code>, <code>direction</code>, <code>page</code>, <code>per_page</code>.</p><h3 id="post-products" tabindex="-1">POST <code>/products</code> <a class="header-anchor" href="#post-products" aria-label="Permalink to &quot;POST `/products`&quot;">​</a></h3><p>Requires <code>products.create</code>. Body: <code>name</code> (required); <code>sku</code> optional (unique per tenant). When <code>sku</code> is omitted or blank, the server auto-generates one (<code>SKU-00001</code> style, or <code>products_sku_prefix</code>). Optional <code>category_id</code>, <code>description</code> (HTML, sanitized server-side, max 50000), <code>unit</code>, <code>cost</code>, <code>price</code>, <code>currency</code>, <code>track_stock</code>, <code>reorder_level</code>, <code>status</code>.</p><h3 id="get-put-delete-products-product" tabindex="-1">GET/PUT/DELETE <code>/products/{product}</code> <a class="header-anchor" href="#get-put-delete-products-product" aria-label="Permalink to &quot;GET/PUT/DELETE `/products/{product}`&quot;">​</a></h3><p>View, update, or soft-delete a product. Update requires <code>products.update</code>; delete requires <code>products.delete</code>. Show embeds notes and activities <strong>newest-first</strong> (<code>created_at</code> DESC, then <code>id</code> DESC).</p><h3 id="post-products-product-restore" tabindex="-1">POST <code>/products/{product}/restore</code> <a class="header-anchor" href="#post-products-product-restore" aria-label="Permalink to &quot;POST `/products/{product}/restore`&quot;">​</a></h3><p>Requires <code>products.restore</code>.</p><h3 id="delete-products-product-force" tabindex="-1">DELETE <code>/products/{product}/force</code> <a class="header-anchor" href="#delete-products-product-force" aria-label="Permalink to &quot;DELETE `/products/{product}/force`&quot;">​</a></h3><p>Requires <code>products.force.delete</code>; product must already be soft-deleted.</p><h3 id="post-products-product-notes" tabindex="-1">POST <code>/products/{product}/notes</code> <a class="header-anchor" href="#post-products-product-notes" aria-label="Permalink to &quot;POST `/products/{product}/notes`&quot;">​</a></h3><p>Requires <code>products.update</code>. Body: <code>{ &quot;body&quot;: &quot;string&quot; }</code>.</p><h3 id="get-products-product-timeline" tabindex="-1">GET <code>/products/{product}/timeline</code> <a class="header-anchor" href="#get-products-product-timeline" aria-label="Permalink to &quot;GET `/products/{product}/timeline`&quot;">​</a></h3><p>Returns product activity entries.</p><h2 id="product-categories" tabindex="-1">Product categories <a class="header-anchor" href="#product-categories" aria-label="Permalink to &quot;Product categories&quot;">​</a></h2><p>Categories use the same module and Products permissions.</p><ul><li><code>GET /product-categories</code> — list</li><li><code>POST /product-categories</code> — create (<code>name</code> required; optional <code>description</code>)</li><li><code>GET|PUT|DELETE /product-categories/{productCategory}</code> — view, update, soft-delete</li><li><code>POST /product-categories/{productCategory}/restore</code> — restore</li><li><code>DELETE /product-categories/{productCategory}/force</code> — permanently delete a soft-deleted category</li></ul><p>Deleting a category leaves associated products intact with <code>category_id = null</code>.</p>',25)])])}const m=t(r,[["render",a]]);export{h as __pageData,m as default};
